from __future__ import annotations

import os
import subprocess
from pathlib import Path
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from thirdparty.internal.model.recipe import RecipeBase


class CMakeToolchain:
    """Generates a CMake toolchain file used by CMake.configure()."""

    def __init__(self, recipe: RecipeBase, generator: str | None = "Ninja") -> None:
        self._recipe = recipe
        self.generator: str | None = generator
        self.variables: dict[str, Any] = {}
        self.cache_variables: dict[str, Any] = {}
        self.preprocessor_definitions: dict[str, Any] = {}

    def generate(self) -> None:
        lines: list[str] = ["# Generated by ThirdParty CMakeToolchain\n"]
        if self.generator:
            lines.append(f"# generator: {self.generator}\n")

        # CMake 4.x removed support for cmake_minimum_required VERSION < 3.5;
        # set this policy variable so old projects don't error out.
        lines.append('set(CMAKE_POLICY_VERSION_MINIMUM "3.5" CACHE STRING "" FORCE)\n')

        if self._recipe.dep_package_paths:
            paths = ";".join(p.replace("\\", "/") for p in self._recipe.dep_package_paths)
            lines.append(f'set(CMAKE_PREFIX_PATH "{paths}" CACHE STRING "" FORCE)\n')

        for key, value in self.cache_variables.items():
            cmake_type, cmake_value = _to_cmake(value)
            cmake_value = cmake_value.replace("\\", "/")
            lines.append(f'set({key} "{cmake_value}" CACHE {cmake_type} "" FORCE)\n')

        for key, value in self.variables.items():
            cmake_type, cmake_value = _to_cmake(value)
            cmake_value = cmake_value.replace("\\", "/")
            lines.append(f'set({key} "{cmake_value}" CACHE {cmake_type} "" FORCE)\n')

        if self.preprocessor_definitions:
            defs = " ".join(
                f"{k}={v}" if not isinstance(v, bool) and v != 1 else k
                for k, v in self.preprocessor_definitions.items()
            )
            lines.append(f"add_compile_definitions({defs})\n")

        toolchain_path = Path(self._recipe.build_folder) / "thirdparty_toolchain.cmake"
        toolchain_path.parent.mkdir(parents=True, exist_ok=True)
        toolchain_path.write_text("".join(lines), encoding="utf-8")


class CMakeDeps:
    """Dependency resolution via CMAKE_PREFIX_PATH (set by CMakeToolchain)."""

    def __init__(self, recipe: RecipeBase) -> None:
        self._recipe = recipe

    def set_property(self, *args, **kwargs) -> None:
        pass  # No-op — ThirdParty uses CMAKE_PREFIX_PATH, not CMake config targets

    def generate(self) -> None:
        pass  # Prefix paths are written by CMakeToolchain.generate()


class CMake:
    """Wraps cmake subprocess calls for configure / build / install."""

    def __init__(self, recipe: RecipeBase) -> None:
        self._recipe = recipe

    def configure(
        self,
        variables: dict[str, Any] | None = None,
        build_script_folder: str | None = None,
    ) -> None:
        src = build_script_folder or self._recipe.source_folder
        toolchain = Path(self._recipe.build_folder) / "thirdparty_toolchain.cmake"

        cmd: list[str] = ["cmake", src, "--fresh"]

        generator = _read_generator(Path(self._recipe.build_folder))
        if generator:
            cmd += ["-G", generator]

        if toolchain.exists():
            cmd += [f"-DCMAKE_TOOLCHAIN_FILE={toolchain}"]
        # Must be a command-line -D arg, not in the toolchain file, because
        # cmake_minimum_required() is evaluated before the toolchain is read.
        cmd += ["-DCMAKE_POLICY_VERSION_MINIMUM=3.5"]
        cmd += [
            f"-DCMAKE_BUILD_TYPE={self._recipe.build_type}",
            f"-DCMAKE_INSTALL_PREFIX={self._recipe.package_folder}",
        ]

        if variables:
            for key, value in variables.items():
                _, cmake_value = _to_cmake(value)
                cmd += [f"-D{key}={cmake_value}"]

        Path(self._recipe.build_folder).mkdir(parents=True, exist_ok=True)
        env = _msvc_env() if generator and "Ninja" in generator else None
        _run(cmd, cwd=self._recipe.build_folder, env=env)

    def build(self, target: str | None = None, build_type: str | None = None) -> None:
        bt = build_type or self._recipe.build_type
        cmd = [
            "cmake", "--build", ".",
            "--config", bt,
            "--parallel", str(os.cpu_count() or 1),
        ]
        if target:
            cmd += ["--target", target]
        # Re-use the same env so Ninja/MSVC can find Windows SDK libs during compile.
        generator = _read_generator(Path(self._recipe.build_folder))
        env = _msvc_env() if generator and "Ninja" in generator else None
        _run(cmd, cwd=self._recipe.build_folder, env=env)

    def install(self, build_type: str | None = None) -> None:
        bt = build_type or self._recipe.build_type
        _run(["cmake", "--install", ".", "--config", bt], cwd=self._recipe.build_folder)


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _to_cmake(value: Any) -> tuple[str, str]:
    if isinstance(value, bool):
        return "BOOL", "ON" if value else "OFF"
    return "STRING", str(value)


def _read_generator(build_dir: Path) -> str | None:
    """Return the generator name recorded in the toolchain file, or None."""
    tc = build_dir / "thirdparty_toolchain.cmake"
    if not tc.exists():
        return None
    for line in tc.read_text(encoding="utf-8").splitlines():
        if line.startswith("# generator:"):
            return line.split(":", 1)[1].strip()
    return None


def _msvc_env() -> dict[str, str] | None:
    """Source vcvarsall.bat x64 and return the resulting environment.

    Returns None when vcvarsall cannot be found (non-MSVC / non-Windows).
    Needed for Ninja generator which does not run vcvarsall automatically,
    so the linker can locate kernel32.lib and other Windows SDK libraries.
    Derives the vcvarsall path from the same cl.exe glob used by recipes so
    the correct VS installation is always selected.
    """
    import glob as _glob

    # Find cl.exe, sorted by MSVC toolchain version (newest last).
    cl_paths = _glob.glob(
        r"C:\Program Files\Microsoft Visual Studio\*\*\VC\Tools\MSVC\*\bin\Hostx64\x64\cl.exe"
    )
    if not cl_paths:
        return None

    def _msvc_ver(p: str) -> tuple[int, ...]:
        try:
            return tuple(int(x) for x in p.split("MSVC\\")[1].split("\\")[0].split("."))
        except Exception:
            return (0,)

    cl_paths.sort(key=_msvc_ver)
    cl_exe = cl_paths[-1]  # newest

    # vcvarsall.bat sits at <VS_root>\VC\Auxiliary\Build\vcvarsall.bat
    vc_dir = cl_exe.split("VC\\Tools")[0] + "VC"
    vcvarsall = os.path.join(vc_dir, "Auxiliary", "Build", "vcvarsall.bat")
    if not os.path.exists(vcvarsall):
        return None

    result = subprocess.run(
        f'call "{vcvarsall}" x64 && set',
        shell=True, capture_output=True, text=True,
    )
    if result.returncode != 0:
        return None

    env: dict[str, str] = dict(os.environ)
    for line in result.stdout.splitlines():
        if "=" in line:
            k, v = line.split("=", 1)
            env[k] = v
    return env


def _run(cmd: list[str], cwd: str, env: dict[str, str] | None = None) -> None:
    result = subprocess.run(cmd, cwd=cwd, env=env, check=False)
    if result.returncode != 0:
        raise RuntimeError(
            f"cmake command failed (exit {result.returncode}):\n  {' '.join(cmd)}"
        )
